<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientDpopBoundAccessTokensAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientDpopBoundAccessTokensAccessor trait.
 *
 * Covers null default, string/VO assignment via withDpopBoundAccessTokens,
 * getDpopBoundAccessTokens/dpopBoundAccessTokens accessors, and isDpopBoundAccessTokensChanged with/without original.
 */
class TrustedClientDpopBoundAccessTokensAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDpopBoundAccessTokens creates a new instance with the DpopBoundAccessTokens set
     * from a string value, and getDpopBoundAccessTokens returns the primitive string.
     */
    public function testWithDpopBoundAccessTokensFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDpopBoundAccessTokensAccessorUnitTest();

        // Act
        $result = $holder->withDpopBoundAccessTokens(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isDpopBoundAccessTokens());
    }
    /**
     * Asserts that withdpopBoundAccessTokens has access to the value object
     * from a string value, and getDpopBoundAccessTokens returns the primitive string.
     */
    public function testWithDpopBoundAccessTokensFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDpopBoundAccessTokensAccessorUnitTest();

        // Act
        $result = $holder->withDpopBoundAccessTokens(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->dpopBoundAccessTokens()->value());
    }
    public function testChangedDpopBoundAccessTokens(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDpopBoundAccessTokensAccessorUnitTest()->withDpopBoundAccessTokens(true);
        $original = $holder->withDpopBoundAccessTokens(true);
        $same = $holder->withDpopBoundAccessTokens(true);
        $modified = $holder->withDpopBoundAccessTokens(false);

        // Act
        $withSame = $original->isDpopBoundAccessTokensChanged($same);
        $withDiferent = $original->isDpopBoundAccessTokensChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientDpopBoundAccessTokensAccessorUnitTest
{
    use TrustedClientDpopBoundAccessTokensAccessor;
}
